from common import *
import io
m=load(); out=io.StringIO()
def P(*a): print(*a,file=out)
P("# Paper 04 — AHRF obstetric-access analyses (public data only)\n")
P("Generated by `p04b.py` 2026-11-27. Sources: HRSA AHRF 2024-2025 (OB-GYN MDs non-federal 2023 [AMA Masterfile]; hospitals with obstetric care 2023 [AHA Annual Survey]; APN midwives w/ NPI 2023; 3-year average births and preterm births 2021-2023 [NCHS natality]; Census 2023 population estimates); CHR 2026 supplement (LBW 2018-2024); CHR 2025 (poverty, %Black, segregation).\n")
m['births']=m.ahrf_births3yr
tot=m.births.sum()
P("## A. Obstetric access (82 counties)\n")
rows=[]
no_h=m[m.ahrf_hosp_ob23==0]
for lab,mask in [('No hospital with obstetric care (AHA 2023)',m.ahrf_hosp_ob23==0),
                 ('No OB-GYN and no hospital with obstetric care',(m.ahrf_hosp_ob23==0)&(m.ahrf_obgyn23==0)),
                 ('No OB-GYN, no obstetric hospital, no NPI midwife',(m.ahrf_hosp_ob23==0)&(m.ahrf_obgyn23==0)&(m.ahrf_midwife_npi23==0)),
                 ('No OB-GYN (any)',m.ahrf_obgyn23==0)]:
    s=m[mask]; rows.append([lab,len(s),f"{len(s)/82*100:.0f}%",round(s.births.sum()),f"{s.births.sum()/tot*100:.1f}%",f"{s.nonmetro.mean()*100:.0f}%",f"{s.dra_county.mean()*100:.0f}%"])
P(pd.DataFrame(rows,columns=['Definition','Counties','% of 82','Avg annual births (2021-23)','% of state births','% nonmetro','% DRA']).to_markdown(index=False)); P()
P(f"Statewide: {int(m.ahrf_obgyn23.sum())} non-federal OB-GYN MDs; {int(m.ahrf_hosp_ob23.sum())} hospitals with obstetric care in {int((m.ahrf_hosp_ob23>0).sum())} counties; {int(m.ahrf_midwife_npi23.sum())} APN midwives with NPI. Preterm births (3-yr avg 2021-23), population-weighted statewide: {m.ahrf_preterm3yr.sum()/m.loc[m.ahrf_preterm3yr.notna(),'births'].sum()*100:.1f}% of births (counties with preterm published).\n")
P("## B. Outcomes by obstetric-hospital presence (county level; unweighted medians and birth-weighted means)\n")
rows=[]
for y,ly in [('preterm_pct','Preterm births % (2021-23)'),('lbw_pct','Low birth weight % all (2018-24)'),('lbw_black','LBW % Black'),('lbw_white','LBW % White'),('teen_birth_rate','Teen births /1,000')]:
    a=m[m.ob_hospital_any==1][y].dropna(); b=m[m.ob_hospital_any==0][y].dropna()
    u=stats.mannwhitneyu(a,b).pvalue if len(a)>2 and len(b)>2 else np.nan
    rows.append([ly,len(a),a.median(),len(b),b.median(),u])
P(pd.DataFrame(rows,columns=['Outcome','n with OB hosp','median','n without OB hosp','median','Mann-Whitney p']).to_markdown(index=False,floatfmt='.3g')); P()
P("## C. Spearman correlations (county level)\n")
rows=[]
for y,ly in [('preterm_pct','Preterm %'),('lbw_pct','LBW %')]:
    for x,lx in [('child_poverty','Child poverty %'),('pct_black_nh','% Black NH'),('obgyn_per10k_fem','OB-GYN per 10k females'),('ahrf_hosp_ob23','# hospitals w/ obstetric care'),('nonmetro','Nonmetro'),('uninsured_pct','Uninsured %'),('pcp_per100k','PCP per 100k')]:
        n,r,p=spearman(m[x],m[y]); rows.append([ly,lx,n,r,p])
P(pd.DataFrame(rows,columns=['Outcome','Predictor','n','rho','p']).to_markdown(index=False,floatfmt='.3f')); P()
P("## D. OLS (HC3), WLS weighted by births\n")
m['pov10']=m.child_poverty/10; m['black10']=m.pct_black_nh/10
for y in ['preterm_pct','lbw_pct']:
    xs=['pov10','black10','ob_hospital_any','nonmetro']
    mod,t,n=ols(m,y,xs); P(f"**{y}** ~ child poverty/10 + %Black/10 + obstetric hospital in county + nonmetro (OLS HC3, n={n}, R2={mod.rsquared:.2f})\n"); P(t.round(3).to_markdown()); P()
    d=m[[y]+xs+['births']].dropna(); X=sm.add_constant(d[xs]); w=sm.WLS(d[y],X,weights=d.births).fit(cov_type='HC3')
    tt=pd.DataFrame({'coef':w.params,'ci_lo':w.conf_int()[0],'ci_hi':w.conf_int()[1],'p':w.pvalues}); P(f"WLS (weights = births), n={len(d)}\n"); P(tt.round(3).to_markdown()); P()
    xs2=['pov10','black10','obgyn_per10k_fem','nonmetro']
    mod,t,n=ols(m,y,xs2); P(f"Alt: OB-GYN per 10k females in place of hospital indicator (n={n}, R2={mod.rsquared:.2f})\n"); P(t.round(3).to_markdown()); P()
P("## E. Black–White LBW gap by obstetric hospital presence\n")
m['gap_lbw']=m.lbw_black-m.lbw_white
a=m[m.ob_hospital_any==1].gap_lbw.dropna(); b=m[m.ob_hospital_any==0].gap_lbw.dropna()
P(f"Median Black–White LBW gap (percentage points): counties with an obstetric hospital {a.median():.1f} (n={len(a)}) vs without {b.median():.1f} (n={len(b)}); Mann-Whitney p={stats.mannwhitneyu(a,b).pvalue:.3f}\n")
cols=['fips','county','nonmetro','dra_county','ahrf_births3yr','ahrf_preterm3yr','preterm_pct','ahrf_obgyn23','ahrf_hosp_ob23','ahrf_midwife_npi23','obgyn_per10k_fem','ob_hospital_any','lbw_pct','lbw_black','lbw_white','child_poverty','pct_black_nh']
m[cols].to_csv('results/p04/p04_county_dataset_ahrf.csv',index=False)
open('results/p04/p04b_results.md','w').write(out.getvalue()); print(out.getvalue())
